import path from 'node:path';
export const resolveWorkspacePath = (root, requested) => {
  if (path.isAbsolute(requested)) throw new Error('absolute paths are not allowed');
  const resolvedRoot = path.resolve(root);
  const candidate = path.resolve(resolvedRoot, requested);
  const relative = path.relative(resolvedRoot, candidate);
  if (relative.startsWith('..') || path.isAbsolute(relative)) throw new Error('path escapes workspace');
  return candidate;
};

