export const handoffOrder = (tasks) => {
  const pending = new Map(Object.entries(tasks).map(([name, deps]) => [name, new Set(deps)]));
  const order = [];
  while (pending.size) {
    const ready = [...pending].filter(([, deps]) => deps.size === 0).map(([name]) => name).sort();
    if (!ready.length) throw new Error('cyclic task graph');
    for (const name of ready) { order.push(name); pending.delete(name); }
    for (const deps of pending.values()) for (const name of ready) deps.delete(name);
  }
  return order;
};

